{
  "name": "rf_scan_update",
  "confidence": "medium",
  "docstring": "Updates an RF scan state machine, applying a new channel configuration when the selected PHY/channel is idle and timeout/busy checks pass, otherwise completing or aborting an active scan slot and updating its packet status flags.",
  "subsystem": "rf",
  "var_renames": {
    "v1": "channel_idx",
    "v2": "tick_us",
    "v3": "phy_idx",
    "v4": "phy_ctx_base",
    "v5": "phy_ctx",
    "v6": "scan_ctx",
    "v7": "channel_state_ptr",
    "v8": "scan_id",
    "v9": "mapped_channel",
    "v10": "scan_slot_base",
    "v11": "scan_slot",
    "v13": "packet_buf",
    "v14": "scan_flags",
    "v16": "remaining_len"
  },
  "struct_hints": [
    {
      "offset": 27,
      "meaning": "scan_ctx: uint8 requested channel id; 0xFF denotes invalid/no channel"
    },
    {
      "offset": 28,
      "meaning": "scan_ctx: uint8 scan/table selector used for channel availability lookup"
    },
    {
      "offset": 29,
      "meaning": "scan_ctx: uint8 PHY/VIF index into the 696-byte PHY context array"
    },
    {
      "offset": 30,
      "meaning": "scan_ctx: uint16 status flags used to gate packet handling and timestamp update"
    },
    {
      "offset": 32,
      "meaning": "scan_ctx: uint16 scan duration or total length passed to rf_apply_cfg and used to compute remaining_len"
    },
    {
      "offset": 34,
      "meaning": "scan_ctx: uint16 result field copied from packet_buf offset 4"
    },
    {
      "offset": 36,
      "meaning": "scan_ctx: uint32 status bits; bit 21 is set when a radio/coexistence busy condition is detected"
    },
    {
      "offset": 64,
      "meaning": "scan_ctx: uint16 timestamp derived from a global base table plus tick/1024"
    },
    {
      "offset": 453,
      "meaning": "channel_state: uint8 scan id/state; value 33 appears to denote idle"
    },
    {
      "offset": 455,
      "meaning": "channel_state: uint8 counter incremented on each check"
    },
    {
      "offset": 444,
      "meaning": "channel_state: uint32 timestamp compared against the 1,000,000 tick idle interval"
    },
    {
      "offset": 448,
      "meaning": "channel_state: uint32 timestamp compared against the 500,000 tick recent-packet interval"
    }
  ]
}
